async function main(ctx) {
  const input = ctx.input || {};
  const command = String(input.command || 'npm test').trim();
  const out = { command };
  if (input.workingDirectory != null && String(input.workingDirectory).trim() !== '') out.workingDirectory = String(input.workingDirectory).trim();
  const t = Number(input.timeout);
  out.timeout = Number.isFinite(t) && t >= 1000 ? t : 600000;
  return out;
}

async function main(ctx) {
  const r = ctx.lastOutputOf('run') || {};
  const exitCode = Number(r.exitCode ?? 1);
  const tail = (s) => { const str = String(s || ''); return str.length > 4000 ? str.slice(-4000) : str; };
  return {
    passed: exitCode === 0,
    exitCode,
    command: r.command || null,
    stdout: tail(r.stdout),
    stderr: tail(r.stderr)
  };
}
